1856	+/// A plain (non-mocktail) fake — same convention
1857	+/// `entries_search_cubit_test.dart`'s own `_FakeEntriesRepository` fake
1858	+/// uses: several tests here need to resolve two calls out of order (the
1859	+/// stale-in-flight-call generation guard), which a single static mocktail
1860	+/// stub can't express as naturally.
1861	+class _FakeDashboardRepository implements DashboardRepository {
1862	+  final List<Either<Failure, DashboardAggregate>> _results = [];
1863	+  final List<Completer<Either<Failure, DashboardAggregate>>> _completers = [];
1864	+  final List<String> calls = [];
1865	+
1866	+  /// When `true`, [getAggregate] returns a `Completer`-backed future the
1867	+  /// test resolves explicitly (via [resolve]) rather than immediately
1868	+  /// returning a queued result.
1869	+  bool gated = false;
1870	+
1871	+  void queue(Either<Failure, DashboardAggregate> result) {
1872	+    _results.add(result);
1873	+  }
1874	+
1875	+  void resolve(int callIndex, Either<Failure, DashboardAggregate> result) {
1876	+    _completers[callIndex].complete(result);
1877	+  }
1878	+
1879	+  @override
1880	+  Future<Either<Failure, DashboardAggregate>> getAggregate({
1881	+    required String period,
1882	+  }) {
1883	+    calls.add(period);
1884	+    if (gated) {
1885	+      final completer = Completer<Either<Failure, DashboardAggregate>>();
1886	+      _completers.add(completer);
1887	+      return completer.future;
1888	+    }
1889	+    if (_results.isEmpty) {
1890	+      throw StateError(
1891	+        'no queued getAggregate() result for call #${calls.length}',
1892	+      );
1893	+    }
1894	+    return Future.value(_results.removeAt(0));
1895	+  }
1896	+}
