1930	+
1931	+/// Collects every state the cubit emits for the duration of [act] — same
1932	+/// helper `entries_search_cubit_test.dart` already documents.
1933	+Future<List<Resource<DashboardAggregate>>> _emittedDuring(
1934	+  DashboardCubit cubit,
1935	+  FutureOr<void> Function() act,
1936	+) async {
1937	+  final emitted = <Resource<DashboardAggregate>>[];
1938	+  final subscription = cubit.stream.listen(emitted.add);
1939	+  await act();
1940	+  // Flushes any state the broadcast `StreamController` has already queued
1941	+  // for delivery but not yet dispatched to this listener (`Cubit.emit`'s
1942	+  // underlying controller is not `sync`) — without this, a `load()` whose
1943	+  // own awaited repository call resolves synchronously can have its final
1944	+  // `emit()` still pending delivery at the exact microtask `act()`'s
1945	+  // returned Future completes on.
1946	+  await Future<void>.delayed(Duration.zero);
1947	+  await subscription.cancel();
1948	+  return emitted;
1949	+}
